import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Bootstrapping Physics-Grounded Video Generation through VLM-Guided Iterative Self-Refinement","description":"","frontmatter":{"title":"Bootstrapping Physics-Grounded Video Generation through VLM-Guided Iterative Self-Refinement","arxiv":"2511.20280","date":"2025-11-25","authors":"Yang Liu, Xilin Zhao, Peisong Wen, Siran Dai, Qingming Huang","categories":"cs.CV","topics":"物理一致视频生成, 多模态思维链, 提示词自精炼","outline":[2,2]},"headers":[],"relativePath":"papers/2511.20280.md","filePath":"papers/2511.20280.md","lastUpdated":null}'),e={name:"papers/2511.20280.md"};function l(i,s,m,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="bootstrapping-physics-grounded-video-generation-through-vlm-guided-iterative-self-refinement" tabindex="-1">Bootstrapping Physics-Grounded Video Generation through VLM-Guided Iterative Self-Refinement <a class="header-anchor" href="#bootstrapping-physics-grounded-video-generation-through-vlm-guided-iterative-self-refinement" aria-label="Permalink to &quot;Bootstrapping Physics-Grounded Video Generation through VLM-Guided Iterative Self-Refinement&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2511.20280" target="_blank" rel="noreferrer">2511.20280</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-11-25</td></tr><tr><td><strong>作者</strong></td><td>Yang Liu, Xilin Zhao, Peisong Wen, Siran Dai, Qingming Huang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>让 VLM 看生成结果挑物理毛病、LLM 把批评改写成新 prompt，如此循环直到 prompt 收敛，全程免训练地把视频模型已有的物理建模能力「问」出来。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">论文性质</p><p>本文是 <strong>ICCV 2025 Physics-IQ Challenge 第三名方案</strong>的技术报告（作者在 arXiv comments 中注明），篇幅约四页，只有方法描述与一张结果表，没有消融实验。下文如实反映这一点。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型的画质已经很好，但生成结果与真实世界物理原理的对齐仍然很差。缩小这个差距是从「视频生成器」走向「世界模型」的关键一步。</p><p>现有的改进路线基本在训练侧：扩大数据与模型规模做大规模预训练，或者基于先进的视觉表示做蒸馏微调。论文提出一个不同的切入点——这些模型可能已经具备一定的物理建模能力，问题在于如何把它<strong>激发出来</strong>。作者引用了 prompt 设计不仅能引导输出、还能触发能力涌现的既有观察，据此认为高质量的 prompt 设计对物理接地的生成是必要的。</p><p>任务是 Physics-IQ 挑战赛的设定：给定一段 3 秒的前缀视频 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 和一句场景描述 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ori</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，生成接下来 5 秒、要求时序连贯且物理上可信的续接。这个设定比纯文生视频更硬——模型不能靠画面漂亮蒙混过关，前 3 秒已经把物体、材质、初速度都确定下来了，后 5 秒必须是这个初始条件的合理演化。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>最直接的前作是 PhyT2V（CVPR 2025），它同样用 LLM 引导的迭代自精炼来做物理接地的文生视频。这条路已经证明了「让语言模型批评生成结果、改写 prompt」是可行的。另有 Think Before You Diffuse 用 LLM 引导物理感知的视频生成，WISA 构建了物理感知的世界模拟器助手，VideoRePA 通过与基础模型的关系对齐来学习物理。</p><p>这些工作的局限各不相同。训练侧的方法（WISA、VideoRePA）需要重新训练或微调，成本高且绑定特定骨干。PhyT2V 这类纯 LLM 引导的方法，反馈环节依赖语言模型对生成视频的<strong>间接</strong>判断——LLM 本身看不见视频，只能基于文本描述推理，这在需要判断「球反弹的高度对不对」这类问题时信息量不足。</p><p>本文与 PhyT2V 的具体差别是把反馈环节升级为多模态：用 VLM 直接观看生成的视频来发现物理违背，而 LLM 只负责把 VLM 的冗长描述改写成视频模型能消化的 prompt。作者把这个过程称为 multimodal chain-of-thought（MM-CoT）。此外任务设定也不同——本文做的是视频续接而非纯文生视频，前缀视频提供了明确的物理初始条件。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从挑战赛的约束出发思考：参赛不能改动闭源或大型视频模型的权重（本文用的是 MAGI-1），能改的只有输入。于是唯一的杠杆是 prompt。</p><p>第一个问题：什么样的 prompt 能提升物理一致性？直觉是把隐含的物理线索显式写出来——「球在 0.4 秒后触地并以约一半的高度反弹」比「球落下」信息量大得多。但人手写这些描述不可扩展，所以需要自动生成。VLM 能看视频、能做物理推理，是这个角色的自然人选。</p><p>第二个问题：VLM 的输出能直接当 prompt 用吗？不能。VLM 被要求做详细的物理预测时会输出很长的分析性文本，与视频模型习惯的 prompt 分布不匹配。所以需要一个改写器，LLM 承担这个角色。</p><p>第三个问题：一次预测就够吗？不够——VLM 是在<strong>没看到生成结果</strong>的情况下做的预测，无法知道模型实际会在哪里出错。把生成的视频再送回 VLM，让它指出实际发生的物理违背，就形成了闭环。这一步是整个方法的核心，也是 self-refinement 的来源。</p><p>第四个问题：什么时候停？作者选了一个朴素但自洽的判据——当 LLM 输出的 prompt 不再变化（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0435em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0435em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span></span></span>）时停止，理由是这表明模型对该场景的物理建模能力已被充分激活。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视频模型对物理的了解，可能比它在默认 prompt 下表现出来的要多；缺的是有人告诉它「这一次你哪里错了」。让一个能看视频的 VLM 充当这个批评者，让一个 LLM 把批评翻译成视频模型听得懂的话，然后重来一遍。反复几轮直到 prompt 不再变化，就意味着能被 prompt 激发的物理能力已经用尽。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>设 VLM 为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span>、LLM 为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>、视频生成模型为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span>。整条流水线分三步。</p><p><strong>Step 1 — 物理感知的文本预测。</strong> 系统输入包含一个简明的物理知识库 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> 与任务指令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span></span></span></span>。对每个样本，VLM 处理 3 秒前缀视频 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0592em;vertical-align:-0.2769em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span></span></span></span> 及其原始描述 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0892em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8305em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ori</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span></span></span></span>，输出一段带显式物理线索的详细预测：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1111em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8641em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1574em;vertical-align:-0.2769em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8805em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ori</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mclose">)</span></span></span></span></span></p><p>这段输出通常冗长且与视频模型的输入分布不匹配，因此用 LLM 改写压缩：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0728em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0728em;vertical-align:-0.2587em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。</p><p><strong>Step 2 — 多模态推理链上的迭代自精炼。</strong> 把简化后的 prompt 与前缀视频送进视频模型生成续接：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0728em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4413em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.091em;vertical-align:-0.2769em;"></span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。生成结果重新交给 VLM 检查物理不一致之处，产出强调「缺失或被违背的物理线索」的新描述，再由 LLM 改写为新 prompt，形成跨迭代的多模态思维链：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1661em;vertical-align:-0.267em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.433em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.267em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2491em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p><strong>Step 3 — 收敛判定与输出。</strong> 当 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1661em;vertical-align:-0.2769em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8892em;"><span style="top:-2.4231em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1031em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1078em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span></span></span></span> 时停止，返回 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0592em;vertical-align:-0.2769em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">gen</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1078em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-2.4413em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span></span></span></span>。</p><p><strong>实现细节。</strong> LLM 用 GPT-4o，VLM 用 Gemini 2.5 Pro，视频模型用 MAGI-1。整套流程搭在 Dify 自动化工作流平台加本地 PyTorch 2.2 环境上。推理步数尝试了 16 和 32 两档，所有生成视频为 5 秒、24 FPS。方法免训练、即插即用，原则上可换任意视频生成模型。</p><p>一个具体的循环示例（基于论文描述的推断）：前缀视频里一杯水正在被倾倒，VLM 先预测「水流将呈连续抛物线落入下方容器，液面上升，杯口有表面张力形成的滞留」；生成后 VLM 发现水流在中途断成了离散水滴且液面没有上升，于是新描述强调「水流保持连续、接收容器液面随时间上升」；LLM 压缩成新 prompt 再生成。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化仅限于把流水线写成函数复合，没有推导。为完整起见解释一下这个记号的含义与意图。</p><p>单轮生成写作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1078em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-2.4413em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.126em;vertical-align:-0.2769em;"></span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>：视频模型以 prompt 和前缀视频为条件产出续接。迭代更新写作</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1661em;vertical-align:-0.267em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.433em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.267em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2491em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7823em;"><span style="top:-2.4231em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>这是一个 prompt 空间上的不动点迭代：算子 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∘</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∘</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span> 把当前 prompt 映射到下一个 prompt，终止条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0435em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0435em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span></span></span></span></span></span></span> 就是寻找 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 的不动点。作者对收敛的解释是「视频模型对该场景物理动力学的建模能力已被充分激活」。</p><p>论文没有给出任何收敛性论证，也没有定义 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span></span></span></span> 的度量（文本相似度？语义等价判断？由谁判定？）。而且 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span> 是随机采样的扩散过程，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 是带温度的自回归模型，因此 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 是一个随机算子，严格意义上的不动点未必存在——实际观察到的「收敛」更可能是 prompt 在若干语义等价表述之间抖动。这属于基于论文内容的推断，作者未讨论。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>迭代真的单调提升吗？</strong> 表 1 给出全部八行结果。16 步推理下：第 1 轮 49.80，第 2 轮 48.31（作者标注为「对不完整 prompt 的部分精炼」），第 3 轮 51.65，第 4 轮 52.92。32 步推理下：第 1 轮 49.49，第 4 轮 49.15（同样标注为部分精炼）。作者的表述是「迭代 prompt 带来一致的性能提升」，但表中数据只在 16 步这一条线上大致成立（49.80 → 52.92，中间还有一次下降），32 步这条线上第 4 轮反而低于第 1 轮。作者自己也承认由于视频复杂度不同，迭代的收益在样本间并不均匀。</p><p><strong>最终成绩从哪来？</strong> 这是全文最需要如实说明的一点：<strong>单次最好的迭代结果是 52.92，低于论文所称的 leaderboard baseline 56.31</strong>。62.38 这个数字来自集成——把多次迭代中最好的输出组合起来。表中给出两档：集成 {1,2,5} 得 57.09，集成全部六次 {1,2,3,4,5,6} 得 62.38。也就是说，相对 baseline 的 +6.07 提升完全由六路集成贡献，迭代自精炼本身单独并未超过 baseline。论文没有说明「最好的输出」是按什么准则挑选的，如果是按 Physics-IQ 分数在测试集上挑，那么这个数字包含了选择偏差（属于推断，论文未澄清）。</p><p><strong>定性结果说明什么？</strong> 作者在五个物理域上做了可视化，结论是对相对简单的物理动力学，视频模型能产出与真实物理贴近的结果。这与「迭代收益不均匀」的观察互相印证——复杂场景大概率是失败的那部分。</p><p><strong>没有做什么？</strong> 论文没有消融：没有拆开 VLM 与 LLM 各自的贡献，没有对比「只用 LLM 不看视频」（即 PhyT2V 式的反馈）与「VLM 看视频」的差异，没有测试换用其他视频生成模型，也没有报告每个样本平均迭代多少轮才收敛。作为四页的挑战赛报告，这是可以理解的，但也意味着「多模态反馈优于纯文本反馈」这个核心区分点并未被实验验证。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视频模型的物理建模能力可能没有被默认 prompt 充分激发，本文用 VLM 看生成结果、LLM 改写批评的闭环把它「问」出来。流水线是 VLM 先基于 3 秒前缀视频做物理预测、LLM 压缩成 prompt、视频模型生成、VLM 再检查违背，如此迭代到 prompt 收敛。方法免训练、即插即用，实现上是 Gemini 2.5 Pro + GPT-4o + MAGI-1 搭在 Dify 工作流上。表中单次最好的迭代结果 52.92 低于 leaderboard baseline 的 56.31，最终 62.38 完全依赖六路输出的集成。作为四页的挑战赛报告，它给出了一条可复用的工程路径，但没有消融来支撑「多模态反馈优于纯文本反馈」这一核心主张。</p><p><strong>3 句话版</strong>：让能看视频的 VLM 当批评者、LLM 当翻译，反复改写 prompt 直到收敛，免训练地提升视频续接的物理一致性。迭代本身的收益不稳定且单次结果未超过 baseline，62.38 的成绩来自六路集成。方法路径清晰，实验证据薄弱。</p><p><strong>1 句话版</strong>：让模型看自己的生成结果挑物理毛病再重写 prompt——有用，但报告里的提升主要来自集成而非迭代。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱、失败代价最大的假设是：<strong>VLM 能可靠地识别生成视频中的物理违背。</strong></p><p>整个闭环的信息增益全部来自这一步。如果 VLM 的判断是噪声，那么 LLM 改写出的新 prompt 就是在随机游走，迭代不会收敛到更好的地方，只会在 prompt 空间里漂移。</p><p>它在实践中很可能不成立，理由有二。第一，VLM 对时间的精细感知本来就弱——判断「反弹高度是否为入射高度的一半」需要在若干帧之间做定量比较，而当前 VLM 在这类任务上的表现远未达到可靠。第二，VLM 与视频生成模型可能共享相同的偏差：两者都在网络视频上训练，如果某种物理错误在训练数据里普遍存在（比如生成式内容中常见的伪重力），VLM 未必会把它标记为错误。</p><p>论文自己的数据其实提供了反面证据：第 2 轮从 49.80 掉到 48.31，32 步的第 4 轮从 49.49 掉到 49.15。两次下降都被标注为「对不完整 prompt 的部分精炼」，但这个解释本身就说明流程不稳定。而集成六次输出才能拿到最好成绩这一事实，与「单次反馈信噪比低、需要多次采样平均掉噪声」的解释高度一致——这恰恰是假设不成立时会看到的现象（属于推断）。</p><p>论文为这个假设提供的证据是：最终分数高于 baseline。但如上所述，这个提升来自集成而非迭代，因此并未直接验证 VLM 反馈的有效性。缺失的关键证据是 VLM 判断的准确率——在一个带人工标注物理错误的小集合上，测量 VLM 指出的违背有多少比例是真的。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要复现完整系统，目标是直接测量 §9 中那个假设。</p><p>数据：从 Physics-IQ 的公开前缀视频中取 50 个场景，用任一可及的视频模型（开源的 Wan 或 CogVideoX 即可，不必是 MAGI-1）各生成 2 条续接，共 100 条。请 2 名标注者对每条视频标出物理违背（类型 + 大致时间段），取一致的部分作为参考答案。</p><p>实现：把同一批视频送进 Gemini 2.5 Pro（或任一可及的 VLM），用与论文同类的提示（物理知识库 + 任务指令）让它列出物理违背。</p><p>测量：VLM 指出的违背与人工标注的匹配率（precision）和覆盖率（recall），并按物理域拆开统计。同时记录一个对照——把<strong>真实</strong>的后 5 秒视频（Physics-IQ 提供真值）也送进 VLM，看它会误报多少不存在的违背。</p><p>判据：如果 precision 低于 0.5，或者在真实视频上的误报率与生成视频相当，那么反馈环节的信噪比不足以支撑迭代，论文的收益必须归因于集成而非自精炼；如果 precision 高且真实视频误报低，则假设成立，接下来值得单独验证迭代（去掉集成，报告单次最好轮次 vs 第 1 轮）。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是给出一个<strong>对 62.38 的替代解释</strong>：这个分数主要来自「多次采样 + 择优」，与物理推理无关。</p><p>攻击实验设计得很直接：保持视频模型、推理步数、生成条数完全一致，但把 prompt 生成方式换成不含任何反馈的版本——用 LLM 对原始描述做 6 次风格各异的改写（不看任何生成视频，纯文本层面的多样化），生成 6 条视频，用与论文相同的集成/择优策略合并。如果这个「无反馈多样性集成」也能达到 60 分附近，那么 MM-CoT 这条闭环的贡献就被证伪，方法退化为一个采样预算的问题。这个对照是论文缺失的最关键一环，因为表 1 中六次生成分别使用了不同的迭代轮次和不同的推理步数（16 与 32），本身就构成了一个多样性集合。</p><p>第二类可预测失败：反馈的方向性。VLM 只被要求指出违背，没有机制保证它指出的违背在下一轮<strong>可被 prompt 修复</strong>。有些物理错误源于模型的架构或训练分布（例如流体的长程一致性），无论 prompt 怎么写都改不了。可预测的后果是：在这类场景上迭代会反复报告同一个问题、prompt 反复强调同一件事却毫无改善，最终因为「prompt 不再变化」而被判定为收敛——收敛判据在这里给出的是假阳性。构造一组已知视频模型无法处理的物理现象（多物体流体交互、长时间的热扩散），统计其迭代轮数与最终得分，若这些场景的收敛轮数反而更短、得分更低，则收敛判据本身是失效的。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动局限：本文（以及 PhyT2V 一类工作）把 prompt 当作唯一的控制杠杆，反馈信号是自然语言。语言是一个极窄的信道——「球应该弹得更低一些」无法表达「反弹系数应为 0.6」，更无法定位到具体是哪一帧哪个区域出了问题。于是反馈的分辨率与生成的分辨率严重不匹配，迭代必然低效。</p><p>新的 framing：把反馈从<strong>语言</strong>换成<strong>可微的时空残差场</strong>，把自精炼从 prompt 空间挪到采样过程中。具体地，不问 VLM「哪里错了」并让它写字，而是要求它输出一张随时间变化的空间置信图（哪些像素区域在哪些时刻是物理可疑的）。这张图可以直接作为下一轮采样的空间-时间权重：在可疑区域重新加噪并局部重采样（类似 inpainting 的重绘），其余区域保持不变。这样每一轮迭代不是重新生成整段视频，而是定向修复，反馈的分辨率与生成的分辨率对齐了。</p><p>可借鉴的相邻工具：图像编辑中的 mask-guided repaint 与 SDEdit（局部重加噪再去噪）；LLM 的 process reward model（把奖励从最终答案下沉到中间步骤）；以及同期论文中 Spotlight（arXiv 2511.18102）提出的错误时间定位任务——它恰好提供了「让 VLM 输出带时间戳的错误」这一能力的基准与度量。</p><p>第一个实验：先不做完整闭环，验证定向重采样是否有效。取一批已知存在局部物理错误的生成视频，用人工标注给出错误的时空掩码（跳过 VLM，先假设定位是完美的），在这些区域做局部重加噪并用相同 prompt 重新去噪，比较修复前后的 Physics-IQ 分数与视觉连贯性。判据：如果 oracle 掩码下的定向重采样能带来明显提升，那么整条路线的上限值得追求，接下来的瓶颈就转移到「VLM 能否输出可用的时空掩码」这一可独立衡量的问题上；如果 oracle 掩码下都提升不明显，说明错误不是局部可修的，物理一致性必须在生成过程的更早阶段解决，那么整个「后验精炼」范式（包括本文）的天花板就被确定了——这同样是一个有价值的结论。</p>',66)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
